    M_FC(1.000,0.100,0.600,1.00),  -- 5 MISC      : PINK
    M_FC(0.800,0.000,0.200,1.00)   -- 6 BRUTAL    : BLOOD RED
}

MM.ROUND_RADIUS=6
MM.M_W=760
MM.M_H=420
MM.HEADER_H=48
MM.TAB_H=34
MM.FOOTER_H=22
MM.ROW_H=26
MM.SLIDER_H=40
MM.LEFT_SHIFT=170
MM.UP_SHIFT=60
MM.IsOpen=false
MM.Built=false
MM.Tab=1
MM.ContentPanels={}
MM.TabWidgets={}
MM.Float=nil
MM.RootSlot=nil
MM._LastMatchKey=nil

function MM:GetMatchKey()
    local key = ""
    pcall(function()
        local GDP = package.loaded["GameLua.GameCore.Data.GameplayData"]
        if GDP then
            local pawn = GDP.GetPlayerCharacter and GDP.GetPlayerCharacter()
            if slua.isValid(pawn) then key = tostring(pawn) end
            if key == "" then
                local pc = GDP.GetPlayerController and GDP.GetPlayerController()
                if slua.isValid(pc) then key = tostring(pc) end
            end
        end
    end)
    return key
end

function MM:ResetUI()
    pcall(function()
        if MM.Float and MM.Float.btn and slua.isValid(MM.Float.btn) then
            MM.Float.btn:RemoveFromParent()
            MM.Float.btn:ConditionalBeginDestroy()
        end
    end)
    pcall(function()
        if MM.Root and slua.isValid(MM.Root) then
            MM.Root:RemoveFromParent()
            MM.Root:ConditionalBeginDestroy()
        end
    end)
    MM.Canvas = nil
    MM.Root = nil
    MM.RootSlot = nil
    MM.Float = nil
    MM.Built = false
    MM.IsOpen = false
    MM.ContentPanels = {}
    MM.TabWidgets = {}
    MM.Tab = 1
end

function MM:CheckMatchChanged()
    local currentKey = self:GetMatchKey()
    if currentKey == "" then return end
    if MM._LastMatchKey == nil then MM._LastMatchKey = currentKey return end
    if MM._LastMatchKey ~= currentKey then
        MM._LastMatchKey = currentKey
        MM:ResetUI()
    end
end

function MM:GetCanvas()
    if MM.Canvas and Game:IsValid(MM.Canvas) then return MM.Canvas end
    MM.Canvas=nil
    pcall(function()
        local T=require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        local M=T.GetMainControlBaseUI()
        if not M or not Game:IsValid(M) then return end
        if M.CanvasPanel_0 and Game:IsValid(M.CanvasPanel_0) then MM.Canvas=M.CanvasPanel_0
        elseif M.CanvasPanel_42 and Game:IsValid(M.CanvasPanel_42) then MM.Canvas=M.CanvasPanel_42 end
    end)
    return MM.Canvas
end

function MM:GetCenterPos()
    local vpW,vpH=0,0
    pcall(function()
        local ui_util=require("client.common.ui_util")
        if ui_util and ui_util.GetViewportSize then
            local vp=ui_util.GetViewportSize()
            if vp and vp.X and vp.X>200 then vpW=vp.X;vpH=vp.Y end
        end
    end)
    if vpW<=200 then
        pcall(function()
            local vx=_G.__AimTouch_ViewportX
            local cy=_G.__AimTouch_CenterY
            if vx and vx>200 then vpW=vx;vpH=(cy and cy>100) and (cy*2) or 1080 end
        end)
    end
    if vpW<=200 then
        pcall(function()
            local GDP=package.loaded["GameLua.GameCore.Data.GameplayData"]
            local PC=GDP and GDP.GetPlayerController and GDP.GetPlayerController()
            if PC and PC.GetViewportSize then
                local FVector2D=import("Vector2D") or _G.FVector2D
                local sz=FVector2D(0,0)
                PC:GetViewportSize(sz)
                if sz and sz.X and sz.X>200 then vpW=sz.X;vpH=sz.Y end
            end
        end)
    end
    if vpW<=200 then
        pcall(function()
            local WLL=import("WidgetLayoutLibrary") or import("/Script/UMG.WidgetLayoutLibrary")
            local GDP=package.loaded["GameLua.GameCore.Data.GameplayData"]
            local PC=GDP and GDP.GetPlayerController and GDP.GetPlayerController()
            if WLL and WLL.GetViewportSize and PC then
                local vp=WLL.GetViewportSize(PC)
                if vp and vp.X and vp.X>200 then vpW=vp.X;vpH=vp.Y end
            end
        end)
    end
    if vpW<=200 then vpW=1920 vpH=1080 end
    local posX=(vpW-MM.M_W)*0.5-MM.LEFT_SHIFT
    local posY=(vpH-MM.M_H)*0.5-MM.UP_SHIFT
    if posX<5 then posX=5 end
    if posY<5 then posY=5 end
    return posX,posY
end

function MM:Recenter()
    if not MM.RootSlot or not mvalid(MM.RootSlot) then return end
    local posX,posY=self:GetCenterPos()
    pcall(function() MM.RootSlot:SetPosition(M_V2(posX,posY)) end)
    pcall(function() MM.RootSlot:SetSize(M_V2(MM.M_W,MM.M_H)) end)
end

function MM:RoundBrush(b,col,w,h)
    if not mvalid(b) then return end
    local r=MM.ROUND_RADIUS or 0
    if r<=0 or w<=12 or h<=12 then return end
    pcall(function()
        local brush=b.Brush
        if not brush then return end
        brush.DrawAs=3
        brush.TintColor=col
        local os=brush.OutlineSettings
        if os then
            local v4=os.CornerRadii
            if v4 then v4.X=r;v4.Y=r;v4.Z=r;v4.W=r end
            os.RoundingType=0
            if os.Color then os.Color=col end
        end
        b:SetBrush(brush)
    end)
end

function MM:Layer(p,x,y,w,h,col,z)
    local b=nil
    pcall(function()
        b=CGame:NewObjectFromPath("/Script/UMG.Border",p)
        if mvalid(b) then
            b:SetBrushColor(col)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            MM:RoundBrush(b,col,w,h)
            local s=p:AddChildToCanvas(b)
            if s then s:SetAutoSize(false);s:SetPosition(M_V2(x,y));s:SetSize(M_V2(w,h));s:SetZOrder(z or 0) end
        end
    end)
    return b
end

function MM:FloatLayer(p,x,y,w,h,col,z)
    local b=nil
    pcall(function()
        b=CGame:NewObjectFromPath("/Script/UMG.Border",p)
        if mvalid(b) then
            b:SetBrushColor(col)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            MM:RoundBrush(b,col,w,h)
            local s=p:AddChildToCanvas(b)
            if s then s:SetAutoSize(false);s:SetPosition(M_V2(x,y));s:SetSize(M_V2(w,h));s:SetZOrder(z or 0) end
        end
    end)
    return b
end

function MM:Text(p,txt,x,y,size,col,z,ax,ay)
    local t=nil
    pcall(function()
        t=CGame:NewObjectFromPath("/Script/UMG.TextBlock",p)
        if mvalid(t) then
            t:SetText(txt)
            if M_SC then t:SetColorAndOpacity(M_SC(col)) else t:SetColorAndOpacity(col) end
            if t.Font then local f=t.Font;f.Size=size;t.Font=f end
            t:SetRenderTransformPivot(M_V2(ax or 0.5,ay or 0.5))
            t:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local s=p:AddChildToCanvas(t)
            if s then s:SetAutoSize(true);s:SetAlignment(M_V2(ax or 0.5,ay or 0.5));s:SetPosition(M_V2(x,y));s:SetZOrder(z or 100) end
        end
    end)
    return t
end

function MM:Btn(p,x,y,w,h,z,onClick)
    local b=nil
    pcall(function()
        b=CGame:NewObjectFromPath("/Script/UMG.Button",p)
        if mvalid(b) then
            pcall(function() b:SetColorAndOpacity(MM.C.transparent) end)
            pcall(function() b:SetBackgroundColor(MM.C.transparent) end)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.Visible)
            local s=p:AddChildToCanvas(b)
            if s then s:SetAutoSize(false);s:SetPosition(M_V2(x,y));s:SetSize(M_V2(w,h));s:SetZOrder(z or 900) end
            if onClick then
                pcall(function() if b.OnClicked then b.OnClicked:Add(function() pcall(onClick) end) end end)
            end
        end
    end)
    return b
end

function MM:UpdateToggle(row)
    if not row then return end
    local st=false
    pcall(function() st=row.GetFunc() end)
    st=st and true or false
    if mvalid(row.checkBox) then
        pcall(function() row.checkBox:SetBrushColor(st and MM.C.emerald or MM.C.ruby_deep) end)
        MM:RoundBrush(row.checkBox,st and MM.C.emerald or MM.C.ruby_deep,18,18)
    end
    if mvalid(row.checkBorder) then
        pcall(function() row.checkBorder:SetBrushColor(st and MM.C.emerald_bright or MM.C.cb_border_off) end)
        MM:RoundBrush(row.checkBorder,st and MM.C.emerald_bright or MM.C.cb_border_off,20,20)
    end
    if mvalid(row.checkMark) then
        pcall(function()
            row.checkMark:SetText(st and "✓" or "")
            if M_SC then
                row.checkMark:SetColorAndOpacity(M_SC(st and MM.C.white or MM.C.text_dim))
            else
                row.checkMark:SetColorAndOpacity(st and MM.C.white or MM.C.text_dim)
            end
        end)
    end
    if mvalid(row.rowBg) then
        pcall(function() row.rowBg:SetBrushColor(st and MM.C.bg_row_alt or MM.C.bg_row) end)
        MM:RoundBrush(row.rowBg,st and MM.C.bg_row_alt or MM.C.bg_row,row.w,row.h)
    end
    if mvalid(row.leftBar) then
        pcall(function() row.leftBar:SetBrushColor(st and MM.C.green_solid or MM.C.ruby) end)
    end
    if mvalid(row.nameText) then
        pcall(function()
            if M_SC then
                row.nameText:SetColorAndOpacity(M_SC(st and MM.C.white or MM.C.text_label))
            else
                row.nameText:SetColorAndOpacity(st and MM.C.white or MM.C.text_label)
            end
        end)
    end
end

function MM:CreateToggleRow(p,item,x,y,w,h,zebra)
    local row={GetFunc=item.GetFunc,SetFunc=item.SetFunc,w=w,h=h}
    local st=false
    pcall(function() st=item.GetFunc() end)
    st=st and true or false
    local rowBg=st and MM.C.bg_row_alt or (zebra and MM.C.bg_row_alt or MM.C.bg_row)

    row.rowBg=MM:Layer(p,x,y,w,h,rowBg,200)
    row.leftBar=MM:Layer(p,x,y,4,h,st and MM.C.green_solid or MM.C.ruby,201)
    MM:Layer(p,x+4,y,w-4,1,st and MM.C.emerald_dim or MM.C.border_soft,202)
    MM:Layer(p,x+4,y+h-1,w-4,1,MM.C.divider,203)

    local cbW=18;local cbH=18
    local cbX=x+14
    local cbY=y+h*0.5-cbH*0.5

    row.checkBorder=MM:Layer(p,cbX-2,cbY-2,cbW+4,cbH+4,st and MM.C.emerald_bright or MM.C.cb_border_off,299)
    row.checkBox=MM:Layer(p,cbX,cbY,cbW,cbH,st and MM.C.emerald or MM.C.ruby_deep,300)
    row.checkMark=MM:Text(p,st and "✓" or "",cbX+cbW*0.5,cbY+cbH*0.5,12,st and MM.C.white or MM.C.text_dim,310,0.5,0.5)
    row.nameText=MM:Text(p,item.Text,cbX+cbW+10,y+h*0.5,11,st and MM.C.white or MM.C.text_label,300,0,0.5)

    MM:Btn(p,x,y,w,h,z or 900,function()
        local nv=not item.GetFunc()
        pcall(function() item.SetFunc(nil,nv) end)
        MM:UpdateToggle(row)
        if _G.ReadLiveConfig then pcall(_G.ReadLiveConfig) end
    end)
    return row
end

function MM:CreateSliderRow(p,item,x,y,w,h,zebra)
    local row={GetFunc=item.GetFunc,SetFunc=item.SetFunc}
    local rowBg=zebra and MM.C.bg_row_alt or MM.C.bg_row

    MM:Layer(p,x,y,w,h,rowBg,200)
    MM:Layer(p,x,y,4,h,MM.C.green_solid,201)
    MM:Layer(p,x+4,y,w-4,1,MM.C.border_soft,202)
    MM:Layer(p,x+4,y+h-1,w-4,1,MM.C.divider,203)

    MM:Text(p,item.Text,x+14,y+6,10,MM.C.text_label,300,0,0.5)

    local minV=item.MinValue or 1
    local maxV=item.MaxValue or 100
    local curV=0
    pcall(function() curV=tonumber(item.GetFunc()) or minV end)
    if curV<minV then curV=minV end
    if curV>maxV then curV=maxV end

    local valText=MM:Text(p,tostring(math.floor(curV)),x+w-14,y+6,11,MM.C.green_solid,310,1,0.5)

    local btnW=36
    local btnH=20
    local btnY=y+h-btnH-4

    local minusX=x+14
    MM:Layer(p,minusX-1,btnY-1,btnW+2,btnH+2,MM.C.ruby_bright,301)
    MM:Layer(p,minusX,btnY,btnW,btnH,MM.C.ruby_deep,302)
    MM:Layer(p,minusX+1,btnY+1,btnW-2,3,MM.C.ruby_dim,303)
    MM:Text(p,"-",minusX+btnW*0.5,btnY+btnH*0.5,16,MM.C.ruby_bright,310,0.5,0.5)

    local plusX=x+w-btnW-14
    MM:Layer(p,plusX-1,btnY-1,btnW+2,btnH+2,MM.C.emerald_bright,301)
    MM:Layer(p,plusX,btnY,btnW,btnH,MM.C.emerald_dim,302)
    MM:Layer(p,plusX+1,btnY+1,btnW-2,3,MM.C.emerald,303)
    MM:Text(p,"+",plusX+btnW*0.5,btnY+btnH*0.5,16,MM.C.white,310,0.5,0.5)

    local barX=minusX+btnW+8
    local barW=plusX-barX-8
    local barY=btnY+btnH*0.5-3
    local barH=6

    MM:Layer(p,barX,barY,barW,barH,MM.C.slider_track,301)
    MM:Layer(p,barX,barY,barW,1,MM.C.border_soft,302)
    MM:Layer(p,barX,barY+barH-1,barW,1,MM.C.border_soft,302)

    local pct=(curV-minV)/(maxV-minV)
    if pct<0 then pct=0 end
    if pct>1 then pct=1 end
    local fillW=math.floor(barW*pct)
    if fillW<3 then fillW=3 end
    local fill=MM:Layer(p,barX,barY,fillW,barH,MM.C.slider_fill,303)
    MM:Layer(p,barX,barY,fillW,2,MM.C.slider_fill_bright,304)

    local step=1

    MM:Btn(p,minusX,btnY,btnW,btnH,900,function()
        local cv=tonumber(item.GetFunc()) or minV
        if cv<minV then cv=minV end
        if cv>maxV then cv=maxV end
        cv=cv-step
        if cv<minV then cv=minV end
        if cv>maxV then cv=maxV end
        pcall(function() item.SetFunc(nil,cv) end)
        pcall(function() valText:SetText(tostring(math.floor(cv))) end)
        local npct=(cv-minV)/(maxV-minV)
        if npct<0 then npct=0 end
        if npct>1 then npct=1 end
        local nfw=math.floor(barW*npct)
        if nfw<3 then nfw=3 end
        pcall(function() local s=fill.Slot;if s then s:SetSize(M_V2(nfw,barH)) end end)
        if _G.ReadLiveConfig then pcall(_G.ReadLiveConfig) end
    end)

    MM:Btn(p,plusX,btnY,btnW,btnH,900,function()
        local cv=tonumber(item.GetFunc()) or minV
        if cv<minV then cv=minV end
        if cv>maxV then cv=maxV end
        cv=cv+step
        if cv<minV then cv=minV end
        if cv>maxV then cv=maxV end
        pcall(function() item.SetFunc(nil,cv) end)
        pcall(function() valText:SetText(tostring(math.floor(cv))) end)
        local npct=(cv-minV)/(maxV-minV)
        if npct<0 then npct=0 end
        if npct>1 then npct=1 end
        local nfw=math.floor(barW*npct)
        if nfw<3 then nfw=3 end
        pcall(function() local s=fill.Slot;if s then s:SetSize(M_V2(nfw,barH)) end end)
        if _G.ReadLiveConfig then pcall(_G.ReadLiveConfig) end
    end)

    return row
end

