    local T={}
    T[#T+1]={name="ESP",items={
        {Text="AUTO ESP (LUA)",GetFunc=function()return _G.PGHACKSConfig.EspVip end,SetFunc=function(c,v)_G.PGHACKSConfig.EspVip=v return true end},
