function MM:BuildMenu()
    if MM.Built and mvalid(MM.Root) then
        pcall(function() MM.Root:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
        MM:Recenter()
        MM.IsOpen=true
        return
    end
    local cv=self:GetCanvas()
    if not cv then return end
    local M_W,M_H,H_H,T_H=self.M_W,self.M_H,self.HEADER_H,self.TAB_H
    local posX,posY=self:GetCenterPos()

    pcall(function()
        MM.Root=CGame:NewObjectFromPath("/Script/UMG.CanvasPanel",cv)
        if mvalid(MM.Root) then
            local s=cv:AddChildToCanvas(MM.Root)
            if s then
                s:SetAutoSize(false)
                s:SetZOrder(10000)
                pcall(function() s:SetAlignment(M_V2(0,0)) end)
                pcall(function() s:SetPosition(M_V2(posX,posY)) end)
                pcall(function() s:SetSize(M_V2(M_W,M_H)) end)
                MM.RootSlot=s
            end
        end
    end)
    if not mvalid(MM.Root) then return end
    local R=MM.Root

    self:Layer(R,-10,-10,M_W+20,M_H+20,self.C.shadow5,-10)
    self:Layer(R,-7,-7,M_W+14,M_H+14,self.C.shadow4,-9)
    self:Layer(R,-4,-4,M_W+8,M_H+8,self.C.shadow3,-8)
    self:Layer(R,-3,-3,M_W+6,M_H+6,self.C.shadow2,-7)
    self:Layer(R,-2,-2,M_W+4,M_H+4,self.C.shadow1,-6)
    self:Layer(R,-3,-3,M_W+6,M_H+6,self.C.red_glow,-5)
    self:Layer(R,-2,-2,M_W+4,M_H+4,self.C.red_glow_soft,-4)
    self:Layer(R,-2,-2,M_W+4,M_H+4,self.C.red_dim,-3)
    self:Layer(R,-1,-1,M_W+2,M_H+2,self.C.red_bright,-2)
    self:Layer(R,0,0,M_W,M_H,self.C.gold,-1)
    self:Layer(R,2,2,M_W-4,M_H-4,self.C.bg_main,1)

    local H_H_ADJ=H_H-4
    self:Layer(R,2,2,M_W-4,H_H_ADJ,self.C.bg_header,4)
    self:Layer(R,2,2,M_W-4,2,self.C.red_bright,5)
    self:Layer(R,2,4,M_W-4,1,self.C.red,6)
    self:Layer(R,2,2+H_H_ADJ-2,M_W-4,1,self.C.gold,5)
    self:Layer(R,2,2+H_H_ADJ-1,M_W-4,1,self.C.gold_bright,6)

    self:Text(R,"PG HACKS",14,2+H_H_ADJ*0.5-7,16,self.C.red_bright,400,0,0.5)
    self:Text(R,"PREMIUM EDITION",14,2+H_H_ADJ*0.5+8,8,self.C.text_dim,400,0,0.5)
    self:Layer(R,128,6+H_H_ADJ*0.5-10,2,20,self.C.red,400)
    self:Text(R,"REAL OWNER WHATSAPP +92 3170025278",M_W*0.5,2+H_H_ADJ*0.5,12,self.C.green_solid,400,0.5,0.5)

    local cX=M_W-34;local cY=2+(H_H_ADJ-24)*0.5
    self:Layer(R,cX-1,cY-1,26,26,self.C.red_bright,395)
    self:Layer(R,cX,cY,24,24,self.C.red,396)
    self:Layer(R,cX+1,cY+1,22,22,self.C.red_deep,397)
    self:Text(R,"X",cX+12,cY+12,14,self.C.white,400,0.5,0.5)
    self:Btn(R,cX,cY,24,24,900,function()
        MM.IsOpen=false
        pcall(function() R:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end)

    local tabs=BuildTabs()
    MM.Tabs=tabs
    local tabY=2+H_H_ADJ
    local tabW=(M_W-4)/#tabs

    self:Layer(R,2,tabY,M_W-4,T_H,self.C.bg_sidebar,4)
    self:Layer(R,2,tabY,M_W-4,1,self.C.gold_dim,5)

    for i=1,#tabs do
        local tx=2+(i-1)*tabW
        local active=(i==1)
        local tabCol=self.TabColors[i] or self.C.red

        local tbg=MM:Layer(R,tx,tabY,tabW,T_H,active and tabCol or self.C.bg_tab_off,10)

        if i<#tabs then MM:Layer(R,tx+tabW-1,tabY+8,1,T_H-16,self.C.divider,13) end

        local txt=self:Text(R,tabs[i].name,tx+tabW*0.5,tabY+T_H*0.5-1,10,active and self.C.white or self.C.text_dim,14,0.5,0.5)

        MM.TabWidgets[i]={bg=tbg,txt=txt,color=tabCol}

        self:Btn(R,tx,tabY,tabW,T_H,900,function()
            MM.Tab=i
            for k=1,#MM.TabWidgets do
                local tw=MM.TabWidgets[k]
                local ison=(k==i)
                if mvalid(tw.bg) then tw.bg:SetBrushColor(ison and tw.color or MM.C.bg_tab_off) end
                if mvalid(tw.txt) then
                    if M_SC then
                        tw.txt:SetColorAndOpacity(M_SC(ison and MM.C.white or MM.C.text_dim))
                    else
                        tw.txt:SetColorAndOpacity(ison and MM.C.white or MM.C.text_dim)
                    end
                end
            end
            for k=1,#MM.ContentPanels do
                if mvalid(MM.ContentPanels[k]) then
                    MM.ContentPanels[k]:SetWidgetVisibility(k==i and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
                end
            end
        end)
    end

    local contentX=2
    local contentY=tabY+T_H
    local contentW=M_W-4
    local contentH=M_H-4-contentY-self.FOOTER_H
    self:Layer(R,contentX,contentY,contentW,contentH,self.C.bg_content,4)

    local padX=14
    local padY=5

    MM.ContentPanels={}
    for ti,tab in ipairs(tabs) do
        local panel=nil
        pcall(function()
            panel=CGame:NewObjectFromPath("/Script/UMG.CanvasPanel",R)
            if mvalid(panel) then
                local s=R:AddChildToCanvas(panel)
                if s then
                    s:SetAutoSize(false)
                    s:SetPosition(M_V2(contentX+padX,contentY+padY))
                    s:SetSize(M_V2(contentW-padX*2,contentH-padY*2))
                    s:SetZOrder(10)
                end
                panel:SetWidgetVisibility(ti==1 and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
            end
        end)
        if not mvalid(panel) then panel=R end
        MM.ContentPanels[ti]=panel

        local innerW=contentW-padX*2
        self:Text(panel,tab.name,innerW*0.5,0,13,self.C.red_bright,100,0.5,0)
        self:Layer(panel,innerW*0.20,22,innerW*0.6,1,self.C.red_bright,101)

        local colGap=12
        local colW=(innerW-colGap)*0.5
        local yPos=30
        local rowGap=4

        local i=1
        local items=tab.items
        while i<=#items do
            local left=items[i]
            local right=items[i+1]
            local leftIsSlider=(left.MinValue~=nil and left.MaxValue~=nil)
            local rightIsSlider=(right and right.MinValue~=nil and right.MaxValue~=nil)

            local rowH=self.ROW_H
            if leftIsSlider then rowH=self.SLIDER_H end
            if rightIsSlider then rowH=self.SLIDER_H end

            if leftIsSlider then
                self:CreateSliderRow(panel,left,0,yPos,colW,rowH,i%2==0)
            else
                self:CreateToggleRow(panel,left,0,yPos,colW,rowH,i%2==0)
            end

            if right then
                if rightIsSlider then
                    self:CreateSliderRow(panel,right,colW+colGap,yPos,colW,rowH,(i+1)%2==0)
                else
                    self:CreateToggleRow(panel,right,colW+colGap,yPos,colW,rowH,(i+1)%2==0)
                end
            end

            yPos=yPos+rowH+rowGap
            i=i+2
        end
    end

    local fY=M_H-2-self.FOOTER_H
    self:Layer(R,2,fY,M_W-4,1,self.C.gold,5)
    self:Layer(R,2,fY+1,M_W-4,self.FOOTER_H-1,self.C.bg_footer,6)

    self:Text(R,"STATUS: ACTIVE",14,fY+self.FOOTER_H*0.5,9,self.C.green_solid,400,0,0.5)
    self:Text(R,"@PGHACKS1 LUA V2",M_W*0.5,fY+self.FOOTER_H*0.5,9,self.C.green_solid,400,0.5,0.5)
    self:Text(R,"TELEGRAM @PGHACKS1",M_W-14,fY+self.FOOTER_H*0.5,9,self.C.green_solid,400,1,0.5)

    MM.Built=true
    MM.IsOpen=true
end

function MM:CreateFloat()
    if mvalid(MM.Float and MM.Float.btn) then
        local hasParent = false
        pcall(function()
            if MM.Float.btn.GetParent then
                local parent = MM.Float.btn:GetParent()
                if parent and slua.isValid(parent) then hasParent = true end
            end
        end)
        if hasParent then return end
        MM.Float=nil
    end
    pcall(function()
        local cv=self:GetCanvas()
        if not cv then return end
        MM.Float={}
        local fW,fH=90,36
        local vpW=1920
        pcall(function()
            local ui_util=require("client.common.ui_util")
            if ui_util and ui_util.GetViewportSize then
                local vp=ui_util.GetViewportSize()
                if vp and vp.X and vp.X>200 then vpW=vp.X end
            end
        end)
        if vpW<=200 then vpW=1920 end
        local fX=(vpW-fW)*0.5 - 145
        local fY=10
        local F=MM.Float

        pcall(function()
            F.btn=CGame:NewObjectFromPath("/Script/UMG.Button",cv)
            if mvalid(F.btn) then
                pcall(function() F.btn:SetColorAndOpacity(self.C.transparent) end)
                pcall(function() F.btn:SetBackgroundColor(self.C.transparent) end)
                F.btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible)
                local s=cv:AddChildToCanvas(F.btn)
                if s then s:SetAutoSize(false);s:SetPosition(M_V2(fX,fY));s:SetSize(M_V2(fW,fH));s:SetZOrder(12002) end
                pcall(function()
                    if F.btn.OnClicked then
                        F.btn.OnClicked:Add(function()
                            pcall(function()
                                MM.IsOpen=not MM.IsOpen
                                if MM.IsOpen then
                                    if MM.Built and mvalid(MM.Root) then
                                        MM:Recenter()
                                        MM.Root:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                                    else
                                        MM:BuildMenu()
                                    end
                                else
                                    if mvalid(MM.Root) then MM.Root:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
                                end
                            end)
                        end)
                    end
                end)
            end
        end)
    end)
end

function MM:Init()
    pcall(function()
        MM:CheckMatchChanged()
        MM:CreateFloat()
        local ticker=require("common.time_ticker")
        if ticker and ticker.AddTimerOnce then
            ticker.AddTimerOnce(2.0,function()
                MM:CheckMatchChanged()
                if not mvalid(MM.Float and MM.Float.btn) then
                    MM.Float=nil
                    MM:CreateFloat()
                end
                if MM.Built and MM.IsOpen then
                    MM:Recenter()
                end
                MM:Init()
            end)
        end
    end)
end

_G.InitPremiumMenu=function()
    local bBtnAlive=false
    pcall(function()
        if _G.PGHACKSMenu and _G.PGHACKSMenu.Float and _G.PGHACKSMenu.Float.btn
           and slua.isValid(_G.PGHACKSMenu.Float.btn) then
            if _G.PGHACKSMenu.Float.btn.GetParent then
                local parent = _G.PGHACKSMenu.Float.btn:GetParent()
                if parent and slua.isValid(parent) then bBtnAlive=true end
            end
        end
    end)
    if _G.PremiumMenuInit and bBtnAlive then return end
    _G.PremiumMenuInit=false
    _G.PremiumMenuInit=true
    _G.EnableLogicESPV2=true
    pcall(function() if _G.LoadESPV2System then _G.LoadESPV2System() end end)
    MM:Init()
    Notify("MENU READY")
end
