-- HIGH JUMP (HOVER/FLY MODE) — Toggle from MISC tab
-- ═══════════════════════════════════════════════════════════════
pcall(function()
    local charMove = localPlayer.CharacterMovement or localPlayer.CharMoveComp
    if not Valid(charMove) then return end

    if _G.PGHACKSConfig.HighJump then
        -- Pehli baar original save karo
        if not _G.PGHACKSState.OrigGravity then
            _G.PGHACKSState.OrigGravity = {
                GravityScale = charMove.GravityScale or 0,
                JumpZVelocity = charMove.JumpZVelocity or 6000.0,
                JumpMaxCount = charMove.JumpMaxCount or 999,
                MaxFallSpeed = charMove.MaxFallSpeed or 200.0
            }
        end

        -- ═══ HOVER MODE ═══
        charMove.GravityScale = 0       -- bahut kam gravity → float effect
        charMove.JumpZVelocity = 3000.0     -- normal jump power

        pcall(function() if charMove.JumpMaxCount then charMove.JumpMaxCount = 9999 end end)
        pcall(function() if charMove.JumpCurrentCount then charMove.JumpCurrentCount = 5 end end)
        pcall(function() if charMove.MaxFallSpeed then charMove.MaxFallSpeed = 100 end end)

        -- Slow fall (no fall damage)
        pcall(function()
            if charMove.MaxFlySpeed then charMove.MaxFlySpeed = 1000 end
        end)

        -- Falling damage OFF
        pcall(function()
            if localPlayer.SetFallingDamageEnabled then
                localPlayer:SetFallingDamageEnabled(false)
            end
            if localPlayer.bCanTakeFallingDamage ~= nil then
                localPlayer.bCanTakeFallingDamage = false
            end
            if localPlayer.bEnableFallingDamage ~= nil then
                localPlayer.bEnableFallingDamage = false
            end
            if localPlayer.FallDamageEnabled ~= nil then
                localPlayer.FallDamageEnabled = false
            end
        end)

        -- Velocity clamp (agar bahut tezi se gir raha ho to slow down)
        pcall(function()
            local vel = charMove.Velocity
            if vel and vel.Z < -50 then
                vel.Z = -50
                charMove.Velocity = vel
            end
        end)

    else
        -- Restore original
        if _G.PGHACKSState.OrigGravity then
            local o = _G.PGHACKSState.OrigGravity
            charMove.GravityScale = o.GravityScale
            charMove.JumpZVelocity = o.JumpZVelocity
            pcall(function() if o.JumpMaxCount and charMove.JumpMaxCount then charMove.JumpMaxCount = o.JumpMaxCount end end)
            pcall(function() if o.MaxFallSpeed and charMove.MaxFallSpeed then charMove.MaxFallSpeed = o.MaxFallSpeed end end)
            pcall(function()
                if localPlayer.SetFallingDamageEnabled then
                    localPlayer:SetFallingDamageEnabled(true)
                end
                if localPlayer.bCanTakeFallingDamage ~= nil then
                    localPlayer.bCanTakeFallingDamage = true
                end
                if localPlayer.bEnableFallingDamage ~= nil then
                    localPlayer.bEnableFallingDamage = true
                end
            end)
            _G.PGHACKSState.OrigGravity = nil
        end
    end
end)

if _G.PGHACKSConfig.FastCar then
    pcall(function()
        local currentVehicle = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
        if Valid(currentVehicle) then
            local rootComp = currentVehicle.RootComponent or (type(currentVehicle.K2_GetRootComponent) == "function" and currentVehicle:K2_GetRootComponent())

            if Valid(rootComp) and type(rootComp.SetAllPhysicsLinearVelocity) == "function" then
                local isAccelerating = false
                local moveComp = currentVehicle.VehicleMovement or currentVehicle.MovementComponent
                if Valid(moveComp) then
                    local throttle = moveComp.ThrottleInput or 0
                    if type(moveComp.GetThrottleInput) == "function" then
                        throttle = moveComp:GetThrottleInput()
                    end
                    if throttle > 0.05 or throttle < -0.05 then
                        isAccelerating = true
                    end
                end
                if currentVehicle.bIsPressingGas or (currentVehicle.Throttle and currentVehicle.Throttle ~= 0) then
                    isAccelerating = true
                end

                local currentVel = nil
                if type(currentVehicle.GetVelocity) == "function" then
                    currentVel = currentVehicle:GetVelocity()
                elseif type(rootComp.GetPhysicsLinearVelocity) == "function" then
                    currentVel = rootComp:GetPhysicsLinearVelocity()
                elseif rootComp.ComponentVelocity then
                    currentVel = rootComp.ComponentVelocity
                end

                if currentVel then
                    local currentSpeed = math.sqrt(currentVel.X^2 + currentVel.Y^2)
                    local minSpeedToBoost = 50.0

                                            local maxSpeed = _G.PGHACKSState.CustomTextData.FastCarSpeed or 3000.0

                                            local accelFactor = 1.5

                    local brakeFactor = 0.85

                    if currentSpeed > minSpeedToBoost then
                        local dirX = currentVel.X / currentSpeed
                        local dirY = currentVel.Y / currentSpeed

                        if isAccelerating then
                            local targetSpeed = currentSpeed * accelFactor
                            if targetSpeed > maxSpeed then targetSpeed = maxSpeed end
                            local newX = dirX * targetSpeed
                            local newY = dirY * targetSpeed
                            local newZ = currentVel.Z
                            rootComp:SetAllPhysicsLinearVelocity(FVector(newX, newY, newZ), false)
                        else
                            local targetSpeed = currentSpeed * brakeFactor
                            if targetSpeed > minSpeedToBoost then
                                local newX = dirX * targetSpeed
                                local newY = dirY * targetSpeed
                                local newZ = currentVel.Z
                                rootComp:SetAllPhysicsLinearVelocity(FVector(newX, newY, newZ), false)
                            end
                        end
                    end
                end
            end
        end
    end)
end

