-- BRUTAL FEATURES — PGHACKSConfig Integrated
-- (Unlimited HP, One Shot Kill, Wall Shoot, Fast Parachute)
-- ═══════════════════════════════════════════════════════════════

-- ───────────────────────────────────────────
-- FEATURE 1: UNLIMITED HP (GOD MODE)
-- ───────────────────────────────────────────
local function ApplyUnlimitedHP()
    pcall(function()
        local GameplayData = require("GameLua.GameCore.Data.GameplayData")
        local player = GameplayData.GetPlayerCharacter()
        if not slua.isValid(player) then return end
        pcall(function() player.Health = math.max(player.Health or 0, 1.0) end)
        pcall(function() player.HealthMax = 9999.0 end)
        pcall(function() player.bCanBeDamaged = false end)
        pcall(function() player.bCanDie = false end)
    end)
end
_G.ApplyUnlimitedHP = ApplyUnlimitedHP

-- ───────────────────────────────────────────
-- FEATURE 2: ONE SHOT KILL
-- ───────────────────────────────────────────
local function ApplyOneShotKill()
    pcall(function()
        local GameplayData = require("GameLua.GameCore.Data.GameplayData")
        local localPlayer = GameplayData.GetPlayerCharacter()
        if not slua.isValid(localPlayer) then return end
        local weaponManager = localPlayer.WeaponManagerComponent
        if not slua.isValid(weaponManager) then return end
        local currentWeapon = weaponManager.CurrentWeaponReplicated
        if not slua.isValid(currentWeapon) then return end
        local shootComp = currentWeapon.ShootWeaponComponent
        if not slua.isValid(shootComp) then shootComp = currentWeapon.ShootWeaponEntityComp end
        if not slua.isValid(shootComp) then return end
        local shootEntity = shootComp.ShootWeaponEntityComponent
        if not slua.isValid(shootEntity) then shootEntity = currentWeapon.ShootWeaponEntityComp end
        if not slua.isValid(shootEntity) then return end
        pcall(function() shootEntity.BulletNumSingleShot = 50 end)
        local extraFields = { "BaseDamage", "Damage", "DamageImpulse", "BulletDamage", "DamageRate" }
        for _, field in ipairs(extraFields) do
            pcall(function()
                if shootEntity[field] ~= nil then shootEntity[field] = 10000.0 end
            end)
        end
    end)
end
_G.ApplyOneShotKill = ApplyOneShotKill

-- ───────────────────────────────────────────
-- FEATURE 3: WALL SHOOT
-- ───────────────────────────────────────────
local function ApplyWallShoot()
    pcall(function()
        local GameplayData = require("GameLua.GameCore.Data.GameplayData")
        local localPlayer = GameplayData.GetPlayerCharacter()
        if not slua.isValid(localPlayer) then return end
        local isEnabled = (_G.PGHACKSConfig and _G.PGHACKSConfig.WallShoot) or false
        local meshContainer = localPlayer.MeshContainer
        local springArmComp = localPlayer.SpringArmComp
        local targetX = 0
        if isEnabled then targetX = 113.0 end
        if slua.isValid(meshContainer) then
            pcall(function()
                local FVector = import("Vector")
                if FVector then
                    local currentLoc = meshContainer.RelativeLocation
                    local newLoc = FVector(targetX, currentLoc.Y or 0, currentLoc.Z or 0)
                    meshContainer.RelativeLocation = newLoc
                end
            end)
        end
        if slua.isValid(springArmComp) then
            pcall(function()
                local FVector = import("Vector")
                if FVector then
                    local targetSpringX = 0
                    if isEnabled then targetSpringX = 133.0 end
                    local currentLoc = springArmComp.RelativeLocation
                    local newLoc = FVector(targetSpringX, currentLoc.Y or 0, currentLoc.Z or 0)
                    springArmComp.RelativeLocation = newLoc
                end
            end)
        end
    end)
end
_G.ApplyWallShoot = ApplyWallShoot

-- ───────────────────────────────────────────
-- FEATURE 4: FAST PARACHUTE
-- ───────────────────────────────────────────
local function ApplyFastParachute()
    pcall(function()
        local GameplayData = require("GameLua.GameCore.Data.GameplayData")
        local localPlayer = GameplayData.GetPlayerCharacter()
        if not slua.isValid(localPlayer) then return end
        local parachuteComp = localPlayer.ParachuteComponent
        if not slua.isValid(parachuteComp) then return end
        pcall(function() parachuteComp.CurrentFallSpeed = 999999 end)
    end)
end
_G.ApplyFastParachute = ApplyFastParachute

-- ───────────────────────────────────────────
-- MASTER LOOP — Sab features ek saath run
-- ───────────────────────────────────────────
local function BrutalFeaturesLoop()
    if _G.PGHACKSConfig then
        if _G.PGHACKSConfig.UnlimitedHP then pcall(ApplyUnlimitedHP) end
        if _G.PGHACKSConfig.OneShotKill then pcall(ApplyOneShotKill) end
        if _G.PGHACKSConfig.WallShoot then pcall(ApplyWallShoot) end
        if _G.PGHACKSConfig.FastParachute then pcall(ApplyFastParachute) end
    end
    local ok, ticker = pcall(require, "common.time_ticker")
    if ok and ticker and ticker.AddTimerOnce then
        ticker.AddTimerOnce(0.1, BrutalFeaturesLoop)
    end
end

local okTicker, tickerMod = pcall(require, "common.time_ticker")
if okTicker and tickerMod and tickerMod.AddTimerOnce then
